"""Private fold-2 Ae-only scale fine-tune; held-out labels are absent from input."""
import os
import base64
import shutil
import subprocess
import sys
from pathlib import Path

INPUT=Path('/kaggle/input')
SLUG='codex-koz3-ae-dfine-f2-s15'
CONFIG_B64=''
ROOT=Path('/kaggle/working/ae_dfine_f2_s15')
print('INPUT_ROOT',[str(p) for p in INPUT.iterdir()],flush=True)
candidates=[INPUT/SLUG/'payload',INPUT/'datasets/solapeolusola'/SLUG/'payload']
candidates+=list(INPUT.glob(f'**/{SLUG}/payload'))
DATASET=next((p for p in candidates if (p/'ae_dfine_finetune.py').is_file()),None)
assert DATASET is not None,f'dataset not mounted; candidates={candidates}'
print('DATASET_ROOT',DATASET,flush=True)
ROOT.mkdir(parents=True,exist_ok=True)
shutil.copytree(DATASET/'koz3',ROOT/'koz3',dirs_exist_ok=True)
(ROOT/'data').mkdir(exist_ok=True)
(ROOT/'data/ae_prep').symlink_to(DATASET/'data/ae_prep',target_is_directory=True)
(ROOT/'data/labels_3857.parquet').symlink_to(DATASET/'data/labels_3857.parquet')
(ROOT/'data/train-expds-3').mkdir(parents=True,exist_ok=True)
(ROOT/'hf_dfine_config').mkdir(exist_ok=True)
(ROOT/'hf_dfine_config/config.json').write_bytes(base64.b64decode(CONFIG_B64))
(ROOT/'work/ae').mkdir(parents=True,exist_ok=True)
(ROOT/'work/ae/ae_dfj_f2.pt').symlink_to(DATASET/'work/ae/ae_dfj_f2.pt')
for script in ('ae_dfine_finetune.py','ae_dfine_scale.py'):
    shutil.copy2(DATASET/script,ROOT/script)

# D-FINE is supported by the tested local Transformers version. The model
# config is bundled; all weights come from the private fold-2 joint checkpoint.
subprocess.run([sys.executable,'-m','pip','install','-q','transformers==5.4.0'],check=True)
env=os.environ.copy()
env.update(KOZ3_ROOT=str(ROOT),HF_HUB_OFFLINE='1',TRANSFORMERS_OFFLINE='1',
           OPENBLAS_NUM_THREADS='1',OMP_NUM_THREADS='4',MKL_NUM_THREADS='4',
           PYTORCH_CUDA_ALLOC_CONF='expandable_segments:True')
print('TRAINING_ONLY_FOLD2_SOURCE; HELDOUT_LABELS_ABSENT',flush=True)
for script,tag in [('ae_dfine_scale.py','scale15')]:
    path=ROOT/script
    subprocess.run([sys.executable,str(path),'--fold','2','--iters','1200'],
                   env=env,cwd=ROOT,check=True)
    subprocess.run([sys.executable,str(path),'--eval-fold','2'],
                   env=env,cwd=ROOT,check=True)
    model_root=ROOT/'Codex Work/ae_yolo_pilot'/('dfine_ft' if tag=='plain' else 'dfine_scale')
    name='codex_ae_ft' if tag=='plain' else 'codex_ae_s15'
    pred=model_root/f'work/ae/oof_{name}_cands.parquet'
    model=model_root/f'work/ae/{name}_f2.pt'
    assert pred.is_file() and model.is_file()
    shutil.copy2(pred,Path('/kaggle/working')/f'ae_{tag}_fold2_oof.parquet')
    shutil.copy2(model,Path('/kaggle/working')/f'ae_{tag}_fold2.pt')
    print('EXPORTED',tag,pred.stat().st_size,model.stat().st_size,flush=True)

# Avoid returning the private input images as notebook output artifacts.
shutil.rmtree(ROOT/'data',ignore_errors=True)
print('AE_DFINE_F2_DONE',flush=True)
